<script setup lang="ts">
import { friendlyError } from '@lostsky/api/client'; import LsAsyncState from '@lostsky/ui/components/LsAsyncState.vue'; import LsButton from '@lostsky/ui/components/LsButton.vue'; import LsEmptyState from '@lostsky/ui/components/LsEmptyState.vue'; import LsInlineError from '@lostsky/ui/components/LsInlineError.vue'; import LsPageHeader from '@lostsky/ui/components/LsPageHeader.vue'; import LsFormSection from '@lostsky/ui/components/LsFormSection.vue'; import LsStatusTag from '@lostsky/ui/components/LsStatusTag.vue'; import { feedback } from '@lostsky/ui/feedback'; import { useMutation,useQuery,useQueryClient } from '@tanstack/vue-query'; import { NInputNumber,NPagination,NSelect,useDialog } from 'naive-ui'; import { computed,ref } from 'vue'; import { useRoute } from 'vue-router'; import { canManage,formatDate,manageApi } from '../../lib'
const route=useRoute();const id=computed(()=>Number(route.params.id));const page=ref(1);const quantity=ref(1);const targetEntityId=ref<number|null>(null);const revealed=ref<Record<number,string>>({});const issued=ref<Array<{id:number;code:string;code_hint:string}>>([]);const client=useQueryClient();const dialog=useDialog();const campaign=useQuery({queryKey:computed(()=>['manage-campaign',id.value]),queryFn:()=>manageApi.campaign(id.value)});const options=useQuery({queryKey:['manage-options'],queryFn:manageApi.options});const query=useQuery({queryKey:computed(()=>['manage-codes',id.value,page.value]),queryFn:()=>manageApi.codes(id.value,{page:page.value,limit:20})});const pages=computed(()=>Math.max(1,Math.ceil(Number(query.data.value?.total??0)/20)));const entityOptions=computed(()=>(options.data.value?.entities??[]).map(e=>({label:e.name,value:Number(e.entity_id??e.id)})));const issue=useMutation({mutationFn:()=>manageApi.issueCodes(id.value,{quantity:quantity.value,target_entity_id:targetEntityId.value}),onSuccess:async rows=>{issued.value=rows;feedback.success(`已发行 ${rows.length} 个兑换码`);await client.invalidateQueries({queryKey:['manage-codes',id.value]})}});async function reveal(codeId:number){const result=await manageApi.revealCode(id.value,codeId);revealed.value={...revealed.value,[codeId]:result.code}}async function copy(value:string){await navigator.clipboard.writeText(value);feedback.success('兑换码已复制')}function stop(codeId:number){dialog.warning({title:'停用兑换码',content:'停用后该兑换码不能继续领取，已经领取的权益不受影响。',positiveText:'确认停用',negativeText:'返回',onPositiveClick:async()=>{await manageApi.disableCode(id.value,codeId);await client.invalidateQueries({queryKey:['manage-codes',id.value]})}})}
</script><template><div class="manage-page"><LsPageHeader :title="campaign.data.value?.name||'兑换码'" description="列表只显示脱敏片段；发行结果和显式查看才展示完整兑换码。" :back-to="`/manage/campaigns/${id}`" back-label="返回活动"/><LsFormSection v-if="canManage('shop.product.write')" title="发行兑换码"><div class="inline-fields"><label>数量<NInputNumber v-model:value="quantity" :min="1" :max="100"/></label><label v-if="Number(campaign.data.value?.mode)===3">定向 Entity<NSelect v-model:value="targetEntityId" :options="entityOptions" filterable placeholder="选择受益 Entity"/></label></div><LsButton :disabled="Number(campaign.data.value?.mode)===3&&!targetEntityId" :loading="issue.isPending.value" @click="issue.mutate()">发行兑换码</LsButton><LsInlineError v-if="issue.isError.value" :message="friendlyError(issue.error.value)"/><div v-if="issued.length" class="issued-codes" role="status"><p>请立即安全保存本次发行结果：</p><button v-for="row in issued" :key="row.id" type="button" @click="copy(row.code)"><code>{{row.code}}</code><span>复制</span></button></div></LsFormSection><LsAsyncState v-if="query.isPending.value" state="loading" :rows="5"/><LsAsyncState v-else-if="query.isError.value" state="error" title="暂时无法读取兑换码" :description="friendlyError(query.error.value)"/><LsEmptyState v-else-if="!query.data.value?.list.length" title="还没有兑换码" description="按活动模式发行第一批兑换码。"/><section v-else class="code-list"><article v-for="row in query.data.value.list" :key="row.id"><div><strong>{{revealed[row.id]||row.code_hint}}</strong><small>#{{row.id}} · {{formatDate(row.create_time)}} · 已使用 {{row.use_count}} 次</small></div><LsStatusTag :label="row.is_active?'可用':'已停用'" :type="row.is_active?'success':'default'"/><div class="row-actions"><LsButton v-if="!revealed[row.id]&&canManage('shop.product.write')" size="sm" variant="secondary" @click="reveal(row.id)">查看</LsButton><LsButton v-else-if="revealed[row.id]" size="sm" variant="secondary" @click="copy(revealed[row.id])">复制</LsButton><LsButton v-if="row.is_active&&canManage('shop.product.write')" size="sm" variant="danger" @click="stop(row.id)">停用</LsButton></div></article></section><div v-if="query.data.value?.total" class="pager"><span>第 {{page}} / {{pages}} 页</span><NPagination v-model:page="page" :page-count="pages"/></div></div></template>
